// @ts-check
// n8n Code node "Split attachments" (mode: run once for all items).
// Turns each email from the trigger into one item per PDF or image attachment, with the file as
// binary property "file". Files that cannot go to Claude are not dropped silently: a file over the
// size limit, or an email without any usable file, becomes an item with status "review" that skips
// Claude and goes straight to the review channel.
const MEDIA_TYPES = {
  'application/pdf': ['pdf'],
  'image/jpeg': ['jpg', 'jpeg'],
  'image/png': ['png'],
  'image/webp': ['webp'],
  'image/gif': ['gif'],
};
// Keeps the base64 form of an image under the API's 5 MB image limit.
const MAX_IMAGE_BYTES = 3.75 * 1024 * 1024;
const MAX_TEXT = 300;

/**
 * @typedef {object} Binary n8n binary data (metadata; in filesystem mode `data` is only a reference).
 * @property {string} [data]
 * @property {string} [id]
 * @property {string} [mimeType]
 * @property {string} [fileName]
 * @property {number} [bytes]
 *
 * @typedef {object} GmailMessage Gmail Trigger output with "Simplify" off (fields used here).
 * @property {string} id
 * @property {string} threadId
 * @property {string[]} [labelIds]
 * @property {{ value?: { address?: string }[], text?: string }} [from]
 * @property {string} [subject]
 * @property {string} [date]
 *
 * @typedef {{ maxPdfMB: number, minImageKB: number, processedLabelId: string, reviewLabelId: string }} Settings
 */

/** @param {Binary} file */
function mediaType(file) {
  const mime = String(file.mimeType ?? '').toLowerCase();
  if (mime in MEDIA_TYPES) return mime;
  // Some mail systems send PDFs as application/octet-stream; the extension is the next best hint.
  const ext = String(file.fileName ?? '')
    .toLowerCase()
    .split('.')
    .pop();
  return Object.keys(MEDIA_TYPES).find((t) => MEDIA_TYPES[/** @type {keyof MEDIA_TYPES} */ (t)].includes(ext ?? ''));
}

/** @param {Binary} file */
function size(file) {
  if (typeof file.bytes === 'number') return file.bytes;
  // Binary kept in memory (no id) has the base64 string itself in `data`.
  return !file.id && file.data ? Math.floor((file.data.length * 3) / 4) : 0;
}

/** @param {number} bytes */
const mb = (bytes) => `${(bytes / 1024 / 1024).toFixed(1)} MB`;

const settings = /** @type {Settings} */ ($('Settings').first().json);
const done = new Set([settings.processedLabelId, settings.reviewLabelId]);
/** @type {{ json: Record<string, unknown>, binary?: Record<string, Binary> }[]} */
const out = [];

for (const item of $('Gmail Trigger').all()) {
  const m = /** @type {GmailMessage} */ (item.json);
  // A manual "Execute workflow" run fetches recent mail again; mail this workflow has already
  // labelled is skipped so it does not produce a second row or review message.
  if ((m.labelIds ?? []).some((id) => done.has(id))) continue;

  const email = {
    message_id: m.id,
    thread_id: m.threadId,
    email_from: String(m.from?.value?.[0]?.address ?? m.from?.text ?? '').slice(0, MAX_TEXT),
    email_subject: String(m.subject ?? '').slice(0, MAX_TEXT),
    received_at: m.date ?? '',
    gmail_link: /^[0-9a-f]+$/i.test(m.id) ? `https://mail.google.com/mail/u/0/#all/${m.id}` : '',
    processed_at: new Date().toISOString(),
  };
  const files = Object.values(/** @type {Record<string, Binary>} */ (item.binary ?? {}));
  let used = 0;
  for (const file of files) {
    const type = mediaType(file);
    const bytes = size(file);
    const fileName = String(file.fileName ?? 'attachment').slice(0, 200);
    if (!type) continue;
    // Small images are logos and icons from email signatures, not scanned receipts.
    if (type !== 'application/pdf' && bytes < settings.minImageKB * 1024) continue;
    used++;
    const limit = type === 'application/pdf' ? settings.maxPdfMB * 1024 * 1024 : MAX_IMAGE_BYTES;
    if (bytes > limit) {
      out.push({
        json: {
          ...email,
          file_name: fileName,
          status: 'review',
          reasons: [`file too large for automatic reading (${mb(bytes)}, limit ${mb(limit)})`],
        },
      });
      continue;
    }
    out.push({
      json: { ...email, file_name: fileName, media_type: type, file_bytes: bytes, status: 'pending', reasons: [] },
      binary: { file },
    });
  }
  if (!used) {
    const names = files.map((f) => f.fileName ?? '?').join(', ');
    out.push({
      json: {
        ...email,
        file_name: names.slice(0, 200),
        status: 'review',
        reasons: [names ? `no PDF or image attachment (found: ${names})` : 'no attachment'],
      },
    });
  }
}

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return out;

// @ts-check
// n8n Code node "Build request" (mode: run once for all items).
// Builds one Anthropic Messages API request per file: the file as a document (PDF) or image block,
// the system prompt, and the JSON schema the reply must follow. Claude reads scanned documents and
// photos directly, so there is no separate OCR step.
const MAX_TOKENS = 16000;

// The declared MIME type of an attachment is set by the sender's mail program and is sometimes
// wrong; the first bytes say what the file is.
const SIGNATURES = [
  ['JVBERi0', 'application/pdf'],
  ['/9j/', 'image/jpeg'],
  ['iVBORw0KGgo', 'image/png'],
  ['R0lGOD', 'image/gif'],
  ['UklGR', 'image/webp'],
];

/**
 * @typedef {{ model: string, effort: string, systemPrompt: string, outputSchema: object }} Settings
 * @typedef {{ fileBase64: string, media_type: string } & Record<string, unknown>} FileItem
 */

/** @param {string} base64 */
const sniff = (base64) => SIGNATURES.find(([prefix]) => base64.startsWith(prefix))?.[1];

const settings = /** @type {Settings} */ ($('Settings').first().json);

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return $input.all().map((item, i) => {
  const { fileBase64, ...file } = /** @type {FileItem} */ (item.json);
  const media_type = sniff(fileBase64) ?? file.media_type;
  const source = { type: 'base64', media_type, data: fileBase64 };
  const block = media_type === 'application/pdf' ? { type: 'document', source } : { type: 'image', source };
  return {
    json: {
      file: { ...file, media_type },
      request: {
        model: settings.model,
        max_tokens: MAX_TOKENS,
        // Thinking stays at the model's default (adaptive); effort keeps it short for a task that
        // is reading, not reasoning. The totals are checked in code afterwards anyway.
        output_config: { effort: settings.effort, format: { type: 'json_schema', schema: settings.outputSchema } },
        system: settings.systemPrompt,
        messages: [
          {
            role: 'user',
            content: [block, { type: 'text', text: 'Extract the data of the attached document.' }],
          },
        ],
      },
    },
    binary: item.binary,
    pairedItem: { item: i },
  };
});

// @ts-check
// n8n Code node "Validate" (mode: run once for all items).
// Turns Claude's reply into an invoice record. Anything that is not a well-formed reply (an API
// error, a refusal, a cut-off or malformed answer) becomes status "review" with the reason, so no
// file is silently dropped. The reply is not trusted: the document it was read from may contain
// text aimed at the model, so every field is checked or clamped here.
const MAX_TEXT = 200;
const MAX_LINE_ITEMS = 100;
const TYPES = ['invoice', 'credit_note', 'receipt', 'not_invoice'];

/**
 * @typedef {object} ClaudeResponse Ask Claude output: a Messages API response, or { error } after failed retries.
 * @property {{ type: string, text?: string }[]} [content]
 * @property {string} [stop_reason]
 * @property {string | { message?: string }} [error]
 *
 * @typedef {Record<string, any>} Extraction Claude's reply, shaped by src/schema.json but not trusted.
 *
 * @typedef {object} Invoice
 * @property {string} status "ok", "review" or "not_invoice"
 * @property {string[]} reasons why the status is not "ok"
 * @property {string} document_type
 * @property {string} supplier_name
 * @property {string} supplier_vat_id
 * @property {string} invoice_number
 * @property {string} invoice_date as printed
 * @property {string} due_date as printed
 * @property {string} currency
 * @property {string} net_amount as printed
 * @property {string} vat_amount as printed
 * @property {string} gross_amount as printed
 * @property {{ rate: string, net: string, vat: string }[]} vat_lines
 * @property {string} iban
 * @property {{ description: string, quantity: string, unit_price: string, amount: string }[]} line_items
 */

/** @param {unknown} v */
const text = (v, max = MAX_TEXT) =>
  String(v ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);

/** @param {ClaudeResponse} res */
function readReply(res) {
  if (res.error)
    throw new Error(
      `API error: ${typeof res.error === 'string' ? res.error : (res.error.message ?? JSON.stringify(res.error))}`,
    );
  if (res.stop_reason === 'max_tokens') throw new Error('model reply cut off at max_tokens');
  if (res.stop_reason === 'refusal') throw new Error('model declined to read the document');
  const reply = (res.content ?? [])
    .filter((c) => c.type === 'text')
    .map((c) => c.text ?? '')
    .join('');
  const start = reply.indexOf('{');
  const end = reply.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('no JSON object in model reply');
  return /** @type {Extraction} */ (JSON.parse(reply.slice(start, end + 1)));
}

/**
 * @param {Extraction} raw
 * @returns {Invoice}
 */
function validate(raw) {
  /** @type {string[]} */
  const reasons = [];
  const type = TYPES.includes(raw.document_type) ? raw.document_type : '';
  if (!type) reasons.push(`unknown document type "${text(raw.document_type, 40)}"`);
  const vatLines = Array.isArray(raw.vat_lines) ? raw.vat_lines.slice(0, 20) : [];
  const lineItems = Array.isArray(raw.line_items) ? raw.line_items.slice(0, MAX_LINE_ITEMS) : [];

  /** @type {Invoice} */
  const inv = {
    status: 'ok',
    reasons,
    document_type: type,
    supplier_name: text(raw.supplier_name),
    supplier_vat_id: text(raw.supplier_vat_id, 40),
    invoice_number: text(raw.invoice_number, 60),
    invoice_date: text(raw.invoice_date, 40),
    due_date: text(raw.due_date, 40),
    currency: text(raw.currency, 10),
    net_amount: text(raw.net_amount, 40),
    vat_amount: text(raw.vat_amount, 40),
    gross_amount: text(raw.gross_amount, 40),
    vat_lines: vatLines.map((/** @type {any} */ l) => ({
      rate: text(l?.rate, 20),
      net: text(l?.net, 40),
      vat: text(l?.vat, 40),
    })),
    iban: text(raw.iban, 50),
    line_items: lineItems.map((/** @type {any} */ l) => ({
      description: text(l?.description, 300),
      quantity: text(l?.quantity, 20),
      unit_price: text(l?.unit_price, 20),
      amount: text(l?.amount, 40),
    })),
  };

  if (type === 'not_invoice') {
    return { ...inv, status: 'not_invoice', reasons: ['not an invoice, credit note or receipt'] };
  }

  const uncertain = (Array.isArray(raw.uncertain_fields) ? raw.uncertain_fields : []).map((f) => text(f, 30));
  if (uncertain.length) reasons.push(`unclear on the document: ${uncertain.join(', ')}`);

  return { ...inv, status: reasons.length ? 'review' : 'ok' };
}

const built = $('Build request').all();
const now = new Date();

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return $input.all().map((item, i) => {
  const { file } = /** @type {{ file: Record<string, unknown> }} */ (built[i].json);
  /** @type {Partial<Invoice> & { status: string, reasons: string[] }} */
  let result;
  try {
    result = validate(readReply(/** @type {ClaudeResponse} */ (item.json)));
  } catch (err) {
    // Ask Claude continues on error, so a failed call (after its retries) arrives here as
    // { error } and goes to review like any other problem.
    result = { status: 'review', reasons: [err instanceof Error ? err.message : String(err)] };
  }
  return {
    json: { ...file, ...result, processed_at: now.toISOString() },
    binary: built[i].binary,
    pairedItem: { item: i },
  };
});
